        tx, ty = target
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        return [dx, dy]

    def is_position_valid(pos, shape):
        rows = shape.get('rows', 0)
        cols = shape.get('cols', 0)
        px, py = pos
        return 0 <= px < cols and 0 <= py < rows

