        target = find_nearest(territories, own_pos)
        if target and is_position_valid(target, shape):
            return move_towards(target)

    # Default move: check surroundings to avoid moving out of bounds
    possible_moves = [
        (-1, 0),  # left
        (1, 0),   # right
        (0, -1),  # up
        (0, 1),   # down
